# 투자론 심화 단원 (기존 iv1~iv9에 추가)
import math
from course_helpers import mc, ox, calc, card, imp, case_card

def _N(x): return 0.5 * (1 + math.erf(x / math.sqrt(2)))
_d1 = (math.log(100 / 100) + (0.05 + 0.5 * 0.2 ** 2) * 1) / (0.2 * 1)
_d2 = _d1 - 0.2
_BS = 100 * _N(_d1) - 100 * math.exp(-0.05) * _N(_d2)

