  mc('영구적 손실의 주된 원인이 아닌 것은?', ['분산된 지수의 일시적 하락', '레버리지에 따른 강제 청산', '한 종목 집중 투자 후 파산', '팔 수 없는 비유동 자산'], ''),
  mc('위기 때 분산 효과가 약해지는 이유는?', ['자산 간 상관관계가 높아져서', '거래 수수료가 내려가서', '배당이 늘어나서', '변동성이 사라져서'], ''),
